import numpy as np
from scipy.ndimage import label

def get_max_component_size(grid, k):
    max_size = 0
    for color in range(k):
        mask = (grid != color)
        labeled_array, num_features = label(mask)
        if num_features == 0:
            continue
        sizes = np.bincount(labeled_array.ravel())
        if len(sizes) > 1:
            max_size = max(max_size, np.max(sizes[1:]))
    return max_size

def test_pattern(k, grid_size=20):
    grid = np.zeros((grid_size, grid_size), dtype=int)
    for r in range(grid_size):
        for c in range(grid_size):
            grid[r, c] = (r + c) % k
    return get_max_component_size(grid, k)

print(f"k=2, pattern: {test_pattern(2)}")
print(f"k=3, pattern: {test_pattern(3)}")

import numpy as np
from scipy.ndimage import label

def get_max_component_size(grid, k):
    max_size = 0
    for color in range(k):
        mask = (grid != color)
        labeled_array, num_features = label(mask)
        if num_features == 0:
            continue
        sizes = np.bincount(labeled_array.ravel())
        if len(sizes) > 1:
            max_size = max(max_size, np.max(sizes[1:]))
    return max_size

def test_linear_pattern(k, a, b):
    grid_size = 50
    grid = np.zeros((grid_size, grid_size), dtype=int)
    for r in range(grid_size):
        for c in range(grid_size):
            grid[r, c] = (a*r + b*c) % k
    return get_max_component_size(grid, k)

for a in range(1, 10):
    for b in range(1, 10):
        print(f"a={a}, b={b}: {test_linear_pattern(3, a, b)}")
